const char* pc_text(PcLanguage language, PcText key) {
    if(language >= PcLanguageCount) language = PcEnglish;
    if(key >= TxCount) return "";
    return translations[language][key] ? translations[language][key] :
                                         translations[PcEnglish][key];
}
